cedar:
@id("permit-effective-capability")
@control("CTL-CAP-001")
permit (
  principal is Betsee::Agent,
  action in Betsee::Action::"agent_action",
  resource
)
when {
  context.session.delegated.contains(context.capability) &&
  context.session.useCase.permitted.contains(context.capability)
};

@id("forbid-capability-not-delegated")
@control("CTL-CAP-001")
forbid (principal, action in Betsee::Action::"agent_action", resource)
unless { context.session.delegated.contains(context.capability) };

@id("forbid-capability-not-permitted-for-use-case")
@control("CTL-CAP-001")
forbid (principal, action in Betsee::Action::"agent_action", resource)
unless { context.session.useCase.permitted.contains(context.capability) };

// Fails closed if the Gateway ever builds a request whose action and capability disagree.

@id("forbid-capability-action-mismatch")
@control("CTL-POL-002")
forbid (principal, action in Betsee::Action::"agent_action", resource)
unless {
  (action == Betsee::Action::"crm.read" && context.capability == Betsee::Capability::"crm.read") ||
  (action == Betsee::Action::"tickets.read" && context.capability == Betsee::Capability::"tickets.read") ||
  (action == Betsee::Action::"files.read" && context.capability == Betsee::Capability::"files.read") ||
  (action == Betsee::Action::"tickets.write" && context.capability == Betsee::Capability::"tickets.write") ||
  (action == Betsee::Action::"memory.write" && context.capability == Betsee::Capability::"memory.write") ||
  (action == Betsee::Action::"email.send" && context.capability == Betsee::Capability::"email.send") ||
  (action == Betsee::Action::"payments.transfer" && context.capability == Betsee::Capability::"payments.transfer") ||
  (action == Betsee::Action::"shell.exec" && context.capability == Betsee::Capability::"shell.exec") ||
  (action == Betsee::Action::"agent.message" && context.capability == Betsee::Capability::"agent.message") ||
  (action == Betsee::Action::"llm.complete" && context.capability == Betsee::Capability::"llm.complete")
};

@id("forbid-session-not-bound-to-agent")
@control("CTL-ID-001")
forbid (principal, action in Betsee::Action::"agent_action", resource)
unless { context.session.agent == principal };

@id("forbid-agent-not-active")
@control("CTL-ID-002")
forbid (principal is Betsee::Agent, action in Betsee::Action::"agent_action", resource)
unless { principal.state == "active" };

@id("forbid-session-not-active")
@control("CTL-ID-003")
forbid (principal, action in Betsee::Action::"agent_action", resource)
unless {
  context.session.status == "active" &&
  context.now < context.session.expiresAt
};

@id("forbid-session-human-not-active")
@control("CTL-ID-004")
forbid (principal, action in Betsee::Action::"agent_action", resource)
unless { context.session.human.active };

@id("forbid-resource-above-session-tier")
@control("CTL-TIER-001")
forbid (
  principal,
  action in Betsee::Action::"agent_action",
  resource is Betsee::Resource
)
when { resource.tier > context.session.tierCeiling };

// No write-down: once a session has read data at tier T, it may not write or send to a
// destination labelled below T. session.taint is the highest tier read so far.

@id("forbid-write-down")
@control("CTL-TIER-002")
forbid (
  principal,
  action in [Betsee::Action::"write", Betsee::Action::"egress"],
  resource is Betsee::Resource
)
when { resource.tier < context.session.taint };

@id("forbid-model-below-session-taint")
@control("CTL-TIER-003")
forbid (
  principal,
  action == Betsee::Action::"llm.complete",
  resource is Betsee::Model
)
when { resource.maxTier < context.session.taint };

@id("forbid-mcp-call-without-tool")
@control("CTL-TOOL-001")
forbid (principal, action in Betsee::Action::"mcp", resource)
unless { context has toolCall };

@id("forbid-tool-descriptor-drift")
@control("CTL-TOOL-001")
forbid (principal, action in Betsee::Action::"agent_action", resource)
when {
  context has toolCall &&
  context.toolCall.tool.pinnedDescriptorHash != context.toolCall.observedDescriptorHash
};

@id("forbid-command-not-validated")
@control("CTL-EXEC-001")
forbid (principal, action == Betsee::Action::"shell.exec", resource)
unless { context has command && context.command.valid };

@id("forbid-a2a-peer-not-allowed")
@control("CTL-A2A-001")
forbid (
  principal,
  action == Betsee::Action::"agent.message",
  resource is Betsee::Agent
)
unless { context.session.useCase.peers.contains(resource) };

@id("forbid-a2a-receiver-not-active")
@control("CTL-A2A-001")
forbid (
  principal,
  action == Betsee::Action::"agent.message",
  resource is Betsee::Agent
)
unless { resource.state == "active" };

@id("forbid-a2a-receiver-below-session-taint")
@control("CTL-A2A-002")
forbid (
  principal,
  action == Betsee::Action::"agent.message",
  resource is Betsee::Agent
)
when { resource.clearance < context.session.taint };

// A message is not a delegation: the sender cannot ask for a capability outside its own
// effective capability set.

@id("forbid-a2a-capability-escalation")
@control("CTL-A2A-003")
forbid (principal, action == Betsee::Action::"agent.message", resource)
unless {
  context has requestedCapability &&
  context.session.delegated.contains(context.requestedCapability) &&
  context.session.useCase.permitted.contains(context.requestedCapability)
};

@id("forbid-budget-exceeded")
@control("CTL-RUN-001")
forbid (principal, action in Betsee::Action::"agent_action", resource)
when { context.session.spentCents + context.costCents > context.session.budgetCents };

@id("forbid-rate-exceeded")
@control("CTL-RUN-002")
forbid (principal, action in Betsee::Action::"agent_action", resource)
when { context.actionsLastMinute > context.session.useCase.maxActionsPerMinute };

@id("approval-required-by-use-case")
@control("CTL-APR-001")
@outcome("require_approval")
forbid (principal, action in Betsee::Action::"agent_action", resource)
when { context.session.useCase.approvalRequired.contains(context.capability) }
unless { context.approval.granted };

@id("step-up-required-by-use-case")
@control("CTL-APR-002")
@outcome("require_step_up")
forbid (principal, action in Betsee::Action::"agent_action", resource)
when { context.session.useCase.stepUpRequired.contains(context.capability) }
unless { context.approval.stepUp };

@id("forbid-payment-without-amount")
@control("CTL-APR-003")
forbid (principal, action == Betsee::Action::"payments.transfer", resource)
unless { context has amountCents && context.amountCents > 0 };

@id("approval-payment-above-threshold")
@control("CTL-APR-003")
@outcome("require_approval")
forbid (principal, action == Betsee::Action::"payments.transfer", resource)
when {
  context has amountCents &&
  context.amountCents > context.session.useCase.approvalThresholdCents
}
unless { context.approval.granted };

@id("step-up-payment-above-threshold")
@control("CTL-APR-003")
@outcome("require_step_up")
forbid (principal, action == Betsee::Action::"payments.transfer", resource)
when {
  context has amountCents &&
  context.amountCents > context.session.useCase.approvalThresholdCents
}
unless { context.approval.stepUp };

// After a session ingested untrusted content (an inbound ticket, another agent's message), a
// high-impact action needs a human.

@id("approval-high-impact-after-untrusted-input")
@control("CTL-PROV-001")
@outcome("require_approval")
forbid (principal, action in Betsee::Action::"high_impact", resource)
when { context.session.untrustedInput }
unless { context.approval.granted };

@id("analyzer-malicious")
@control("CTL-AI-001")
forbid (principal, action in Betsee::Action::"agent_action", resource)
when { context has analysis && context.analysis.verdict == "malicious" };

@id("analyzer-suspicious")
@control("CTL-AI-001")
@outcome("require_approval")
forbid (principal, action in Betsee::Action::"agent_action", resource)
when { context has analysis && context.analysis.verdict == "suspicious" }
unless { context.approval.granted };

@id("permit-session-delegation-within-entitlements")
@control("CTL-DEL-001")
permit (
  principal is Betsee::Human,
  action == Betsee::Action::"session.create",
  resource is Betsee::Agent
)
when {
  principal.active &&
  principal.entitlements.containsAll(context.delegated) &&
  context.useCase.permitted.containsAll(context.delegated)
};

@id("forbid-session-tier-above-ceiling")
@control("CTL-DEL-002")
forbid (
  principal is Betsee::Human,
  action == Betsee::Action::"session.create",
  resource is Betsee::Agent
)
when {
  context.tierCeiling > principal.clearance ||
  context.tierCeiling > context.useCase.tierCeiling ||
  context.tierCeiling > resource.clearance
};

@id("forbid-session-agent-not-registered-for-use-case")
@control("CTL-DEL-003")
forbid (principal, action == Betsee::Action::"session.create", resource is Betsee::Agent)
unless { context.useCase.agents.contains(resource) };

@id("forbid-session-for-inactive-agent")
@control("CTL-ID-002")
forbid (principal, action == Betsee::Action::"session.create", resource is Betsee::Agent)
unless { resource.state == "active" };

// Mirrors of the permit so a refused delegation names the side that failed.

@id("forbid-session-delegation-exceeds-human-entitlements")
@control("CTL-DEL-001")
forbid (principal is Betsee::Human, action == Betsee::Action::"session.create", resource)
unless { principal.entitlements.containsAll(context.delegated) };

@id("forbid-session-delegation-exceeds-use-case")
@control("CTL-DEL-001")
forbid (principal, action == Betsee::Action::"session.create", resource)
unless { context.useCase.permitted.containsAll(context.delegated) };

@id("forbid-session-create-human-not-active")
@control("CTL-ID-004")
forbid (principal is Betsee::Human, action == Betsee::Action::"session.create", resource)
unless { principal.active };

@id("tpl-suspend-high-impact")
@control("CTL-RUN-004")
forbid (principal in ?principal, action in Betsee::Action::"high_impact", resource);
